(function(root){
const E=typeof module!=='undefined'?require('./engine.js'):root.Expense,P=typeof module!=='undefined'?require('./payroll.js'):root.ExpensePayroll;
function salaryRows(summary,roster,history=[]){return roster.map(e=>{const email=P.normalizeEmail(e.email),matches=summary.filter(x=>x.email===email),run=summary[0]?.runId;if(roster.filter(x=>P.normalizeEmail(x.email)===email).length!==1)return {...e,error:'DUPLICATE PAYROLL EMAIL'};if(history.some(h=>h.runId===run&&h.email===email))return {...e,error:'ALREADY PROCESSED'};if(matches.length!==1||matches[0].employeeId!==e.id)return {...e,error:'CHECK EMPLOYEE EMAIL / IMPORT'};const x=matches[0];if(!x.ready||!Number.isFinite(e.base)||!Number.isFinite(e.adjustment||0))return {...e,error:'CHECK EXPENSES'};return {...e,runId:x.runId,email,periodCAD:x.periodCAD,lateCAD:x.lateCAD,reimbursementCAD:x.totalCAD,claimCount:x.claims,finalCAD:E.round(e.base+x.totalCAD+(e.adjustment||0)),status:'Ready for payment'};});}
function simulate(){const s=E.seed();s.claims=[];s.batches=[];s.ledger=[];s.settlements=[];s.audit=[];const salaries=s.employees.map((e,i)=>({...e,base:[1200,950,1400][i],adjustment:[0,-25,15][i]}));
const periods=[{month:'September 2026',from:'2026-08-10',to:'2026-09-09',paymentDate:'2026-09-08',includeLate:true},{month:'October 2026',from:'2026-09-10',to:'2026-10-09',paymentDate:'2026-10-12',includeLate:true},{month:'November 2026',from:'2026-10-10',to:'2026-11-09',paymentDate:'2026-11-10',includeLate:true}];let n=0;
function add(employee,date,status='Approved',amount=500,currency='BDT'){const id='LAB-EXP-'+String(++n).padStart(3,'0'),approved=status==='Approved';const c={id,employee:employee.name,employeeId:employee.id,date,status,stage:approved?'Complete':'HR',category:'Other',categorySchema:structuredClone(s.categoryDefs.Other),vendor:'Fictional payroll-lab vendor '+n,purpose:'Fictional business expense',receipt:'fictional-bill.pdf',receiptKey:'builtin:'+id,receiptHash:'lab:'+id,paidBy:'Personal',amount,currency,approvals:{hr:approved?{status:'Approved',actor:'Demo HR',amount,reason:'Fictional evidence checked'}:{status:'Pending'}}};if(approved){c.approved=amount;c.approvalCAD=E.round(amount*s.rates[currency]);}s.claims.push(c);return c;}
periods.forEach((o,m)=>s.employees.forEach((e,i)=>{add(e,o.from,'Approved',[600,18,2800][i],['BDT','USD','PKR'][i]);add(e,o.to.slice(0,8)+'05','Approved',200+100*i,'BDT');}));
const early=add(s.employees[0],'2026-09-09','Approved',700),late=add(s.employees[1],'2026-08-05','Submitted',350),pending=add(s.employees[2],'2026-10-20','Submitted',500),rejected=add(s.employees[1],'2026-10-22','Rejected',900),company=add(s.employees[0],'2026-10-25','Approved',1000);company.paidBy='Company';
P.connectEmails(s,s.employees.map(e=>e.email));const months=[],history=[];
for(let i=0;i<periods.length;i++){const o=periods[i];if(i===1)E.review(s,late.id,'HR','Demo HR','Approved','Late fictional bill now validated',350);const preview=P.preview(s,o),r=P.autoSync(s,o),summary=P.summary(s,r.runId),payroll=salaryRows(summary,salaries,history);if(payroll.some(x=>x.error))throw Error('Demo payroll identity check failed');const run=s.payrollRuns.find(x=>x.id===r.runId),refs=[];for(const bid of run.batchIds){const b=s.batches.find(x=>x.id===bid),ref='FICTIONAL-'+String(i+1)+'-'+b.employee.replace(/ /g,'-');E.pay(s,bid,o.paymentDate,ref);refs.push({employee:b.employee,batch:bid,reference:ref});}payroll.forEach(row=>{row.status='Paid · fictional';row.paymentDate=o.paymentDate;row.reference=refs.find(x=>x.employee===row.name).reference;history.push({runId:r.runId,email:row.email});});const duplicate=salaryRows([...summary,...summary],salaries,[]),wrong=salaryRows(summary,salaries.map((e,j)=>j===0?{...e,email:'wrong@bevycommerce.com'}:e),[]),reused=salaryRows(summary,salaries,history);months.push({...o,runId:r.runId,summary:structuredClone(summary),payroll,preview:preview.entries.map(x=>({id:x.claim.id,employee:x.claim.employee,date:x.claim.date,group:x.group,reason:x.reason})),claimIds:P.runRows(s,r.runId).map(x=>x.claim),duplicate,wrong,reused,totalCAD:E.round(payroll.reduce((a,x)=>a+x.finalCAD,0)),reimbursementCAD:E.round(payroll.reduce((a,x)=>a+x.reimbursementCAD,0))});}
return {months,history,claims:structuredClone(s.claims),settlements:s.settlements,ledger:s.ledger,book:E.reimbursementSummary(s),special:{early:early.id,late:late.id,pending:pending.id,rejected:rejected.id,company:company.id},note:'Isolated fictional payroll simulation; no real salaries, Google writes or transfers.'};}
const api={simulate,salaryRows};if(typeof module!=='undefined')module.exports=api;else root.ExpensePayrollLab=api;
})(globalThis);
